}

import React from 'react';
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { 
  CheckCircle2, Shield, 
  Activity, Gavel, Building, Stethoscope,
  Download, Share2, Users
} from "lucide-react";
import { ChatMessage, PersonaOutput, ValidationMetric } from './types';

interface DetailedResponseViewProps {
  message: ChatMessage;
}

export function DetailedResponseView({ message }: DetailedResponseViewProps) {
  // Use data from message if available, otherwise fallback to defaults for UI state
  const personas: (PersonaOutput & { icon: React.ReactNode })[] = (message.personas || [
    {
      id: "p1",
      name: "Knowledge Expert",
      role: "Healthcare Systems & Law",
      icon: <Stethoscope className="h-4 w-4 text-blue-400" />,
      confidence: 99.7,
      contribution: "Identified AES-256 & TLS 1.3 requirements. Noted 7-year audit log retention.",
      avatar: "≡ƒ⌐║",
      weight: 0.25,
      sources: []
    },
    {
      id: "p2",
      name: "Sector Specialist",
      role: "IT Ops & Cloud Arch",
      icon: <Building className="h-4 w-4 text-orange-400" />,
      confidence: 99.4,
      contribution: "Emphasized BAAs and data residency. Specified RTO < 4 hours.",
      avatar: "≡ƒÅó",
      weight: 0.25,
      sources: []
    },
    {
      id: "p3",
      name: "Regulatory Advisor",
      role: "HIPAA Attorney",
      icon: <Gavel className="h-4 w-4 text-purple-400" />,
      confidence: 99.8,
      contribution: "Mapped 45 CFR ┬º 164.308/312. Flagged HITECH & State laws.",
      avatar: "ΓÜû∩╕Å",
      weight: 0.25,
      sources: []
    },
    {
      id: "p4",
      name: "Compliance Officer",
      role: "CISO & Auditor",
      icon: <Shield className="h-4 w-4 text-green-400" />,
      confidence: 99.5,
      contribution: "Validated SOC2/ISO alignment. Created 14-point risk checklist.",
      avatar: "≡ƒ¢í∩╕Å",
      weight: 0.25,
      sources: []
    }
  ]).map(p => ({
    ...p,
    // Ensure icon exists for UI display
    icon: (p as any).icon || <Users className="h-4 w-4 text-blue-400" />
  }));

  const metrics: (ValidationMetric & { label: string, value: string })[] = (message.metrics || [
    { name: "FACTUAL_ACCURACY", score: 0.998, status: "pass", details: "Verified vs 23 sources" },
    { name: "LEGAL_VALIDITY", score: 0.996, status: "pass", details: "8 regulatory codes" },
    { name: "COMPLETENESS", score: 0.984, status: "pass", details: "All aspects covered" },
    { name: "CONSISTENCY", score: 0.999, status: "pass", details: "Zero contradictions" },
    { name: "BIAS_SCORE", score: 0.02, status: "pass", details: "Threshold < 0.05" },
    { name: "SAFETY_CHECK", score: 1, status: "pass", details: "No harmful content" },
  ]).map(m => ({
    ...m,
    label: m.name.replace(/_/g, ' ').toLowerCase().split(' ').map(s => s.charAt(0).toUpperCase() + s.substring(1)).join(' '),
    value: m.score > 1 ? m.score.toString() : `${(m.score * 100).toFixed(1)}%`,
    detail: m.details // compatibility mapping
  } as any));

  return (
    <div className="space-y-6 mt-4">
       {/* ≡ƒö¼ VALIDATION METRICS */}
       <div className="bg-black/30 border border-white/10 rounded-lg p-4">
          <h3 className="text-xs font-bold text-gray-500 uppercase tracking-wider mb-3 flex items-center gap-2">
             <Activity className="h-3 w-3" /> Validation Metrics
          </h3>
          <div className="grid grid-cols-3 gap-3">
             {metrics.map((m, i) => (
                <div key={i} className="bg-white/5 border border-white/5 p-2 rounded flex flex-col">
                   <div className="flex justify-between items-start mb-1">
                      <span className="text-[10px] text-gray-400 uppercase">{m.label}</span>
                      {m.status === 'pass' && <CheckCircle2 className="h-3 w-3 text-green-500" />}
                   </div>
                   <div className="text-lg font-bold text-white leading-none mb-1">{m.value}</div>
                   <div className="text-[10px] text-gray-500 truncate">{(m as any).detail}</div>
                </div>
             ))}
          </div>
       </div>

       {/* ≡ƒÄ¡ QUAD PERSONA ANALYSIS */}
       <div className="border border-white/10 rounded-lg overflow-hidden">
          <div className="bg-white/5 p-3 border-b border-white/10 flex justify-between items-center">
             <h3 className="text-xs font-bold text-gray-300 uppercase tracking-wider flex items-center gap-2">
                <Users className="h-3 w-3 text-blue-400" /> Quad Persona Analysis
             </h3>
             <Badge variant="outline" className="text-[10px] h-5 border-blue-500/30 text-blue-400">Consensus: 98.7%</Badge>
          </div>
          
          <div className="divide-y divide-white/10">
             {personas.map(persona => (
                <div 
                  key={persona.id} 
                  className="p-3 bg-black/20 hover:bg-white/5 transition-colors cursor-pointer group"
                >
                   <div className="flex items-start justify-between mb-2">
                      <div className="flex items-center gap-2">
                         <div className="p-1 rounded bg-white/5 border border-white/10">{persona.icon}</div>
                         <div>
                            <div className="text-sm font-bold text-gray-200 group-hover:text-white">{persona.name}</div>
                            <div className="text-[10px] text-gray-500">{persona.role}</div>
                         </div>
                      </div>
                      <div className="text-right">
                         <div className="text-xs font-bold text-green-400">{persona.confidence}%</div>
                         <div className="text-[9px] text-gray-600 uppercase">Confidence</div>
                      </div>
                   </div>
                   <p className="text-xs text-gray-400 pl-9 border-l-2 border-white/10 ml-2">
                      {persona.contribution}
                   </p>
                </div>
             ))}
          </div>
       </div>

       {/* Actions */}
       <div className="flex justify-end gap-2 pt-2">
          <Button variant="ghost" size="sm" className="h-7 text-xs text-gray-400 hover:text-white gap-2">
             <Download className="h-3 w-3" /> Report
          </Button>
          <Button variant="ghost" size="sm" className="h-7 text-xs text-gray-400 hover:text-white gap-2">
             <Share2 className="h-3 w-3" /> Share
          </Button>
       </div>
    </div>
  );
}

import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { 
  CheckCircle2, Clock, PlayCircle, 
  ZoomIn
} from "lucide-react";
import { TraceStep } from './types';

export function TraceVisualizer() {
  const steps: TraceStep[] = [
    { id: '1', name: 'TruthGate Security', status: 'completed', durationMs: 100, percentage: 100, timestamp: '0.1s' },
    { id: '2', name: 'Coordinate Resolution', status: 'completed', durationMs: 300, percentage: 100, timestamp: '0.4s' },
    { id: '3', name: 'Knowledge Graph Query', status: 'completed', durationMs: 500, percentage: 100, timestamp: '0.9s' },
    { id: '4', name: 'Quad Persona Sim', status: 'completed', durationMs: 1400, percentage: 100, timestamp: '2.3s' },
    { id: '5', name: 'Deep Neural Analysis', status: 'processing', durationMs: 312, percentage: 68, timestamp: 'CURRENT' },
    { id: '6', name: 'Data Validation', status: 'pending', percentage: 0, timestamp: '---' },
    { id: '7', name: 'Compliance Check', status: 'pending', percentage: 0, timestamp: '---' },
    { id: '8', name: 'Self-Critique', status: 'pending', percentage: 0, timestamp: '---' },
    { id: '9', name: 'Iteration Loop', status: 'pending', percentage: 0, timestamp: '---' },
    { id: '10', name: 'Final Synthesis', status: 'pending', percentage: 0, timestamp: '---' },
  ];

  return (
    <Card className="bg-black/40 border-white/10 mt-6">
      <CardHeader className="py-3 border-b border-white/10 flex flex-row items-center justify-between">
         <CardTitle className="text-sm font-bold flex items-center gap-2">
            <ZoomIn className="h-4 w-4 text-blue-400" /> Interactive Trace Explorer
         </CardTitle>
         <div className="flex gap-2">
            <Badge variant="outline" className="text-[10px] bg-white/5 border-white/10 text-gray-400">Tree View</Badge>
            <Badge variant="outline" className="text-[10px] bg-blue-900/20 border-blue-500/30 text-blue-400">Timeline View</Badge>
         </div>
      </CardHeader>
      <CardContent className="p-4 space-y-4">
         
         {/* Timeline Bar */}
         <div className="relative pt-6 pb-2">
            <div className="absolute top-0 left-0 w-full h-1 bg-white/5 top-[18px]"></div>
            <div className="flex justify-between relative z-10">
               {steps.map((step, i) => (
                  <div key={step.id} className="flex flex-col items-center gap-2 group cursor-pointer">
                     <div className={`
                        w-3 h-3 rounded-full border-2 
                        ${step.status === 'completed' ? 'bg-green-500 border-green-500' : 
                          step.status === 'processing' ? 'bg-blue-500 border-blue-500 animate-pulse' : 
                          'bg-black border-gray-600'}
                     `}></div>
                     <span className={`text-[9px] font-mono max-w-[60px] text-center leading-tight ${step.status === 'pending' ? 'text-gray-600' : 'text-gray-300'}`}>
                        {step.name}
                     </span>
                  </div>
               ))}
            </div>
         </div>

         {/* Detailed Step List */}
         <div className="space-y-1 bg-black/20 rounded-lg p-2 max-h-48 overflow-y-auto custom-scrollbar">
            {steps.map((step) => (
               <div key={step.id} className="flex items-center justify-between p-2 rounded hover:bg-white/5 transition-colors group">
                  <div className="flex items-center gap-3">
                     {step.status === 'completed' && <CheckCircle2 className="h-4 w-4 text-green-500" />}
                     {step.status === 'processing' && <PlayCircle className="h-4 w-4 text-blue-500 animate-spin-slow" />}
                     {step.status === 'pending' && <Clock className="h-4 w-4 text-gray-700" />}
                     
                     <div>
                        <div className={`text-xs font-medium ${step.status === 'pending' ? 'text-gray-600' : 'text-gray-200'}`}>
                           {step.name}
                        </div>
                        {step.status === 'processing' && (
                           <div className="w-24 h-1 bg-gray-800 rounded mt-1 overflow-hidden">
                              <div className="h-full bg-blue-500 animate-progress" style={{ width: `${step.percentage}%` }}></div>
                           </div>
                        )}
                     </div>
                  </div>
                  
                  <div className="text-right">
                     <span className={`text-[10px] font-mono block ${step.status === 'processing' ? 'text-blue-400' : 'text-gray-500'}`}>
                        {step.durationMs ? `${step.durationMs}ms` : '---'}
                     </span>
                     {step.details && <span className="text-[9px] text-gray-600">View Details</span>}
                  </div>
               </div>
            ))}
         </div>

      </CardContent>
    </Card>
  );
}

export interface TraceStep {
  id: string;
  name: string;
  status: 'pending' | 'processing' | 'completed' | 'error';
  durationMs?: number;
  percentage: number;
  details?: Record<string, any>;
  timestamp: string;
}

export interface TracePipeline {
  currentStepId: string;
  steps: TraceStep[];
  totalDurationMs: number;
  estimatedTotalMs: number;
  overallProgress: number;
}

export interface PersonaOutput {
  id: string;
  name: string;
  role: string;
  avatar: string; // emoji or url
  weight: number;
  confidence: number;
  contribution: string;
  sources: string[];
}

export interface ValidationMetric {
  name: string;
  score: number;
  status: 'pass' | 'fail' | 'warn';
  details: string;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  timestamp: string;
  traces?: TracePipeline;
  personas?: PersonaOutput[];
  metrics?: ValidationMetric[];
  finalAnswer?: string; // If content is just a summary
  isEnhanced?: boolean;
}

export interface ChatSession {
  id: string;
  title: string;
  lastMessage: string;
  timestamp: string;
  messages: ChatMessage[];
}

'use client';

import React from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { 
  LayoutDashboard, MessageSquare, Database, Folder, 
  ShieldAlert, Settings, LogOut, Hexagon, X 
} from 'lucide-react';
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";

interface SidebarItemProps {
  icon: React.ElementType;
  label: string;
  href: string;
  isActive: boolean;
  isCollapsed?: boolean;
}

function SidebarItem({ icon: Icon, label, href, isActive, isCollapsed }: SidebarItemProps) {
  return (
    <Link href={href} className={cn("w-full block", isCollapsed ? "flex justify-center" : "")}>
      <div className={cn(
        "flex items-center gap-3 px-3 py-2.5 rounded-lg transition-all duration-200 group relative reveal-hover",
        isActive 
          ? "bg-white/5 text-blue-400 shadow-[0_4px_12px_rgba(0,0,0,0.1)] border border-white/5" 
          : "text-gray-400 hover:text-gray-200 hover:bg-white/5",
        isCollapsed && "justify-center px-0 w-10 h-10"
      )}>
        <Icon className={cn("h-5 w-5 shrink-0 transition-all duration-300", isActive ? "text-blue-400 drop-shadow-[0_0_8px_rgba(59,130,246,0.5)]" : "text-gray-500 group-hover:text-gray-300")} />
        
        {!isCollapsed && (
          <span className={cn("text-base-fluent transition-colors", isActive ? "text-blue-100 font-semibold" : "")}>
            {label}
          </span>
        )}
        
        {isActive && !isCollapsed && (
             <div className="absolute left-0 w-1 h-5 rounded-r-full bg-blue-500 shadow-[0_0_8px_rgba(59,130,246,0.8)]"></div>
        )}
      </div>
    </Link>
  );
}

export function AppSidebar() {
  const pathname = usePathname();
  const [isCollapsed, setIsCollapsed] = React.useState(false);

  // Helper to determine active state
  const isActive = (path: string) => {
      if (path === '/dashboard' && pathname === '/dashboard') return true;
      if (path !== '/dashboard' && pathname?.startsWith(path)) return true;
      return false;
  };

  return (
    <div className={cn(
      "h-screen fluent-acrylic border-r border-white/5 flex flex-col transition-all duration-300 z-50 shadow-2xl",
      isCollapsed ? "w-20" : "w-64"
    )}>
      
      {/* Brand Header */}
      <div className="h-16 flex items-center px-6 border-b border-white/5">
        <div className="flex items-center gap-3 cursor-pointer group" onClick={() => setIsCollapsed(!isCollapsed)}>
           <div className="h-8 w-8 rounded-lg bg-gradient-to-br from-blue-600 to-indigo-700 flex items-center justify-center shrink-0 shadow-lg shadow-blue-900/20 group-hover:scale-105 transition-transform">
              <Hexagon className="h-5 w-5 text-white fill-white/20" />
           </div>
           {!isCollapsed && (
              <div className="animate-in fade-in slide-in-from-left-2 duration-300">
                 <h1 className="font-bold text-sm tracking-wide text-white">UKG<span className="text-gray-500 mx-1">/</span>REGISTRY</h1>
                 <div className="text-[10px] text-gray-500 font-mono tracking-wider">ENTERPRISE v2.4</div>
              </div>
           )}
        </div>
      </div>

      {/* Navigation */}
      <div className="flex-1 py-6 px-3 space-y-2 overflow-y-auto custom-scrollbar">
         <div className={cn("text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-2 px-3 transition-opacity duration-300", isCollapsed && "text-center opacity-0 h-0 overflow-hidden")}>
            Menu
         </div>
         
         <SidebarItem icon={LayoutDashboard} label="Dashboard" href="/dashboard" isActive={isActive('/dashboard')} isCollapsed={isCollapsed} />
         <SidebarItem icon={MessageSquare} label="Enterprise AI" href="/chat" isActive={isActive('/chat')} isCollapsed={isCollapsed} />
         <SidebarItem icon={Database} label="MCP Hub" href="/mcp" isActive={isActive('/mcp')} isCollapsed={isCollapsed} />
         <SidebarItem icon={Folder} label="Projects" href="/projects" isActive={isActive('/projects')} isCollapsed={isCollapsed} />
         
         <div className="my-4 border-t border-white/5 mx-2"></div>
         
         <div className={cn("text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-2 px-3 transition-opacity duration-300", isCollapsed && "text-center opacity-0 h-0 overflow-hidden")}>
            System
         </div>
         
         <SidebarItem icon={ShieldAlert} label="Admin" href="/admin" isActive={isActive('/admin')} isCollapsed={isCollapsed} />
         <SidebarItem icon={Settings} label="Settings" href="/settings" isActive={isActive('/settings')} isCollapsed={isCollapsed} />
      </div>

      {/* User Footer */}
      <div className="p-4 border-t border-white/5 bg-black/20">
        <div className={cn("flex items-center gap-3", isCollapsed ? "justify-center" : "")}>
           <div className="h-9 w-9 rounded-full bg-gradient-to-tr from-gray-700 to-gray-600 border border-white/10 flex items-center justify-center shrink-0 ring-2 ring-transparent group-hover:ring-blue-500/50 transition-all">
              <span className="text-xs font-bold text-white">SC</span>
           </div>
           
           {!isCollapsed && (
              <div className="flex-1 min-w-0 animate-in fade-in slide-in-from-left-2 duration-300">
                 <div className="text-sm font-medium text-white truncate">Sarah Connor</div>
                 <div className="text-xs text-blue-400 truncate">System Admin</div>
              </div>
           )}
           
           {!isCollapsed && (
             <Button variant="ghost" size="icon" className="h-8 w-8 text-gray-500 hover:text-white hover:bg-white/5 shrink-0">
                <LogOut className="h-4 w-4" />
             </Button>
           )}
        </div>
      </div>
    </div>
  );
}

export interface McpServer {
  id: string;
  name: string;
  type: 'enterprise' | 'devops' | 'data' | 'other';
  status: 'connected' | 'disconnected' | 'error';
  url: string;
  protocol: 'websocket' | 'stdio' | 'sse';
  toolsCount: number;
  resourcesCount: number;
  promptsCount: number;
  latencyMs: number;
  lastActivity: string;
  errorMessage?: string;
}

export interface McpTool {
  name: string;
  server: string;
  category: string;
  description: string;
  isEnabled: boolean;
  callsToday: number;
  avgTimeMs: number;
  successRate: number;
  version?: string;
  complexity?: string;
  inputSchema?: Record<string, any>;
  outputSchema?: Record<string, any>;
}

export interface McpResource {
  name: string;
  server: string;
  uri: string;
  description: string;
  isEnabled: boolean;
}

export interface McpPrompt {
  name: string;
  server: string;
  description: string;
  variables: string[];
}

export interface McpStats {
  activeServers: number;
  activeClients: number;
  totalTools: number;
  messagesToday: number;
}

import type { Meta, StoryObj } from '@storybook/react';
import { Button } from '@/components/ui/button';
import { Plus, Settings } from 'lucide-react';

const meta = {
  title: 'Fluent UI/Primitives/Button',
  component: Button,
  parameters: {
    layout: 'centered',
  },
  tags: ['autodocs'],
  argTypes: {
    variant: {
      control: 'select',
      options: ['default', 'destructive', 'outline', 'secondary', 'ghost', 'link'],
    },
    size: {
      control: 'select',
      options: ['default', 'sm', 'lg', 'icon'],
    },
  },
} satisfies Meta<typeof Button>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: {
    children: 'Standard Button',
    variant: 'default',
  },
};

export const Ghost: Story = {
  args: {
    children: 'Ghost Action',
    variant: 'ghost',
  },
};

export const WithIcon: Story = {
  render: (args) => (
    <Button {...args}>
      <Plus className="mr-2 h-4 w-4" /> New Item
    </Button>
  ),
  args: {
    variant: 'default',
  },
};

export const FluentShadow: Story = {
  args: {
    children: 'High Elevation',
    className: 'shadow-lg shadow-blue-900/20 bg-blue-600 hover:bg-blue-700',
  },
};

